// Parse Granola markdown for structured metadata
const raw = Buffer.from($binary.data.data, 'base64').toString('utf-8');

// Extract **Participants:** line
let participants = [];
const partMatch = raw.match(/\*\*Participants:\*\*\s*(.+?)(?:\n|$)/i);
if (partMatch) {
  const entries = partMatch[1].split(',');
  for (const entry of entries) {
    const m = entry.trim().match(/^([A-Za-z][A-Za-z .'-]+?)(?:\s*\(([^)]+)\))?$/);
    if (m) {
      participants.push({ name: m[1].trim(), company: m[2] ? m[2].trim() : null, email: null });
    }
  }
}

// Extract **Date:** line
let meetingDate = null;
const dateMatch = raw.match(/\*\*Date:\*\*\s*(.+?)(?:\n|$)/i);
if (dateMatch) {
  const parsed = new Date(dateMatch[1].trim());
  if (!isNaN(parsed.getTime())) {
    meetingDate = parsed.toISOString().split('T')[0];
  }
}

// Split into granola_summary (structured notes before transcript) and transcript
// Granola typically puts "## Transcript" or "---" before the raw transcript
let granolaSummary = null;
let transcript = raw;
const transcriptMarker = raw.search(/^## Transcript|^---$/m);
if (transcriptMarker > 0) {
  granolaSummary = raw.substring(0, transcriptMarker).trim();
  transcript = raw.substring(transcriptMarker).replace(/^## Transcript\s*\n?|^---\s*\n?/m, '').trim();
}

return [
  {
    json: {
      transcript: transcript,
      filename: $('Watch Granola Folder').item.json.name,
      participants: participants,
      meeting_date: meetingDate,
      granola_summary: granolaSummary
    }
  }
];
